	//조문스타일(법령형식일때) 
	function f_LsInfoPrint(mode,obj,xValue){
		admRulVO.admRulValue.admRulSeq = el('admRulSeq').value;

		var bdyContentNm = admRulVO.bdyUpdValue.updateContentNm;
		if(admRulVO.admRulValue.admRulSeq != ""){

