					openScrollPop("admRulSideInfoPrint.do?contentNm=" + encodeURIComponent(contentNm));
				}else{
					f_LsInfoSave(obj);
				}
			}else if(bdyContentNm.indexOf('admRulOldAndNew') > -1){
				var contentNm = "신구법비교";
				titleNm1 = $("#tmpWidth2").html();
				titleNm2 = $("#tmpWidth3").html();

				if(mode =="1"){
