			form.action = url+".do";
			appendInputEl(form, "hidden", "admRulSeq", el('admRulSeq').value);	
			appendInputEl(form, "hidden", "save", 'save');
			SaveWindow.showInfoSave(obj,0,0);
		}else{
			alert("준비중입니다..");
		}
	}	

